// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity 0.8.28;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IKatanaV3Pool} from "../interfaces/IKatanaV3Pool.sol";

/// @notice Katana V3 arithmetic-mean tick consultation and quote helpers.
/// @dev Tick constants and ratio calculation are adapted from Uniswap V3 TickMath.
library KatanaTwap {
    error InvalidTwapWindow();
    error TickOutOfRange();
    error InvalidOracleLiquidity();

    int24 internal constant MAX_TICK = 887272;

    function consult(address pool, uint32 secondsAgo)
        internal
        view
        returns (int24 arithmeticMeanTick, uint128 harmonicMeanLiquidity)
    {
        if (secondsAgo == 0) revert InvalidTwapWindow();
        uint32[] memory secondsAgos = new uint32[](2);
        secondsAgos[0] = secondsAgo;
        secondsAgos[1] = 0;

        (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s) =
            IKatanaV3Pool(pool).observe(secondsAgos);
        int56 tickDelta = tickCumulatives[1] - tickCumulatives[0];
        uint160 liquidityDelta =
            secondsPerLiquidityCumulativeX128s[1] - secondsPerLiquidityCumulativeX128s[0];
        if (liquidityDelta == 0) revert InvalidOracleLiquidity();

        arithmeticMeanTick = int24(tickDelta / int56(uint56(secondsAgo)));
        if (tickDelta < 0 && tickDelta % int56(uint56(secondsAgo)) != 0) {
            arithmeticMeanTick--;
        }

        uint192 secondsAgoX160 = uint192(secondsAgo) * type(uint160).max;
        harmonicMeanLiquidity =
            uint128(secondsAgoX160 / (uint192(liquidityDelta) << 32));
        if (harmonicMeanLiquidity == 0) revert InvalidOracleLiquidity();
    }

    function getQuoteAtTick(
        int24 tick,
        uint128 baseAmount,
        address baseToken,
        address quoteToken
    ) internal pure returns (uint256 quoteAmount) {
        uint160 sqrtRatioX96 = getSqrtRatioAtTick(tick);
        if (sqrtRatioX96 <= type(uint128).max) {
            uint256 ratioX192 = uint256(sqrtRatioX96) * sqrtRatioX96;
            quoteAmount = baseToken < quoteToken
                ? Math.mulDiv(ratioX192, baseAmount, 1 << 192)
                : Math.mulDiv(1 << 192, baseAmount, ratioX192);
        } else {
            uint256 ratioX128 = Math.mulDiv(sqrtRatioX96, sqrtRatioX96, 1 << 64);
            quoteAmount = baseToken < quoteToken
                ? Math.mulDiv(ratioX128, baseAmount, 1 << 128)
                : Math.mulDiv(1 << 128, baseAmount, ratioX128);
        }
    }

    function getSqrtRatioAtTick(int24 tick) internal pure returns (uint160 sqrtPriceX96) {
        uint256 absTick = tick < 0 ? uint256(-int256(tick)) : uint256(int256(tick));
        if (absTick > uint256(uint24(MAX_TICK))) revert TickOutOfRange();

        unchecked {
            uint256 ratio = absTick & 0x1 != 0
                ? 0xfffcb933bd6fad37aa2d162d1a594001
                : 0x100000000000000000000000000000000;
            if (absTick & 0x2 != 0) ratio = (ratio * 0xfff97272373d413259a46990580e213a) >> 128;
            if (absTick & 0x4 != 0) ratio = (ratio * 0xfff2e50f5f656932ef12357cf3c7fdcc) >> 128;
            if (absTick & 0x8 != 0) ratio = (ratio * 0xffe5caca7e10e4e61c3624eaa0941cd0) >> 128;
            if (absTick & 0x10 != 0) ratio = (ratio * 0xffcb9843d60f6159c9db58835c926644) >> 128;
            if (absTick & 0x20 != 0) ratio = (ratio * 0xff973b41fa98c081472e6896dfb254c0) >> 128;
            if (absTick & 0x40 != 0) ratio = (ratio * 0xff2ea16466c96a3843ec78b326b52861) >> 128;
            if (absTick & 0x80 != 0) ratio = (ratio * 0xfe5dee046a99a2a811c461f1969c3053) >> 128;
            if (absTick & 0x100 != 0) ratio = (ratio * 0xfcbe86c7900a88aedcffc83b479aa3a4) >> 128;
            if (absTick & 0x200 != 0) ratio = (ratio * 0xf987a7253ac413176f2b074cf7815e54) >> 128;
            if (absTick & 0x400 != 0) ratio = (ratio * 0xf3392b0822b70005940c7a398e4b70f3) >> 128;
            if (absTick & 0x800 != 0) ratio = (ratio * 0xe7159475a2c29b7443b29c7fa6e889d9) >> 128;
            if (absTick & 0x1000 != 0) ratio = (ratio * 0xd097f3bdfd2022b8845ad8f792aa5825) >> 128;
            if (absTick & 0x2000 != 0) ratio = (ratio * 0xa9f746462d870fdf8a65dc1f90e061e5) >> 128;
            if (absTick & 0x4000 != 0) ratio = (ratio * 0x70d869a156d2a1b890bb3df62baf32f7) >> 128;
            if (absTick & 0x8000 != 0) ratio = (ratio * 0x31be135f97d08fd981231505542fcfa6) >> 128;
            if (absTick & 0x10000 != 0) ratio = (ratio * 0x9aa508b5b7a84e1c677de54f3e99bc9) >> 128;
            if (absTick & 0x20000 != 0) ratio = (ratio * 0x5d6af8dedb81196699c329225ee604) >> 128;
            if (absTick & 0x40000 != 0) ratio = (ratio * 0x2216e584f5fa1ea926041bedfe98) >> 128;
            if (absTick & 0x80000 != 0) ratio = (ratio * 0x48a170391f7dc42444e8fa2) >> 128;
            if (tick > 0) ratio = type(uint256).max / ratio;
            sqrtPriceX96 =
                uint160((ratio >> 32) + (ratio % (1 << 32) == 0 ? 0 : 1));
        }
    }
}

contracts/MattCoinFlipBurn.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IKatanaV3Pool} from "./interfaces/IKatanaV3Pool.sol";
import {IMattRewardVault} from "./interfaces/IMattRewardVault.sol";
import {KatanaTwap} from "./libraries/KatanaTwap.sol";

/// @title MATT BurnFlip Universal Wager Edition
/// @notice Accepts supported Ronin assets, forwards every wager to the treasury, and settles only in MATT.
/// @dev Uses a future-block commit/reveal outcome and a fixed-window Katana V3 TWAP recorded at bet placement.
contract MattCoinFlipBurn is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum Choice {
        Heads,
        Tails
    }

    enum BetState {
        None,
        Pending,
        Won,
        Lost,
        Expired
    }

    struct AssetConfig {
        address pool;
        uint128 minHarmonicLiquidity;
        bool supported;
    }

    struct Bet {
        address player;
        address asset;
        uint256 wagerAmount;
        uint256 mattEquivalent;
        uint256 payoutAmount;
        uint256 burnAmount;
        uint64 entropyBlock;
        uint64 revealDeadlineBlock;
        int24 meanTick;
        Choice choice;
        BetState state;
        bytes32 commitment;
    }

    error ZeroAddress();
    error UnsupportedAsset(address asset);
    error AssetAlreadySupported(address asset);
    error InvalidPool(address pool);
    error InvalidPoolFactory(address expected, address actual);
    error InvalidPoolPair(address token0, address token1);
    error PoolHasNoLiquidity(address pool);
    error InvalidMattIdentityConfiguration(
        address pool,
        uint128 minHarmonicLiquidity
    );
    error OracleLiquidityTooLow(uint128 actual, uint128 minimum);
    error InvalidMinimumLiquidity();
    error InvalidWagerAmount();
    error WagerTooLarge(uint256 amount);
    error QuoteIsZero();
    error ActiveBetExists(uint256 betId);
    error InsufficientRewardVault(uint256 available, uint256 required);
    error RewardVaultPaused();
    error UnsupportedTokenBehavior();
    error TreasuryTransferFailed();
    error BetNotPending(uint256 betId);
    error NotBetPlayer(address caller, address player);
    error EntropyBlockNotReady(uint256 currentBlock, uint256 requiredBlock);
    error RevealWindowClosed(uint256 currentBlock, uint256 deadlineBlock);
    error RevealWindowStillOpen(uint256 currentBlock, uint256 deadlineBlock);
    error InvalidSecret();
    error EntropyUnavailable();
    error InvalidBasisPoints(uint256 value);
    error InvalidPayoutMultiplier(uint256 value);
    error OutstandingPayoutReservations(uint256 amount);

    address public constant NATIVE_RON = address(0);
    uint256 public constant BPS = 10_000;
    uint32 public constant TWAP_WINDOW = 30 minutes;
    uint16 public constant TARGET_OBSERVATION_CARDINALITY = 32;
    uint64 public constant ENTROPY_DELAY_BLOCKS = 1;
    uint64 public constant REVEAL_WINDOW_BLOCKS = 200;

    IERC20 public immutable matt;
    address public immutable wrappedRon;
    address public immutable katanaV3Factory;
    address payable public immutable treasury;

    IMattRewardVault public rewardVault;
    uint16 public burnBps = 7_500;
    uint32 public payoutMultiplierBps = 20_000;
    uint256 public nextBetId = 1;
    uint256 public reservedPayouts;
    uint256 public totalGames;
    uint256 public totalMattPaid;
    uint256 public totalMattBurned;

    mapping(address asset => AssetConfig config) public assetConfigs;
    mapping(uint256 betId => Bet bet) public bets;
    mapping(address player => uint256 betId) public activeBetOf;

    event SupportedAssetAdded(
        address indexed asset,
        address indexed pool,
        uint128 minHarmonicLiquidity
    );
    event SupportedAssetRemoved(address indexed asset);
    event V3PoolUpdated(
        address indexed asset,
        address indexed previousPool,
        address indexed newPool,
        uint128 minHarmonicLiquidity
    );
    event RewardVaultConfigured(address indexed previousVault, address indexed newVault);
    event BurnBpsConfigured(uint16 previousBps, uint16 newBps);
    event PayoutMultiplierConfigured(uint32 previousBps, uint32 newBps);
    event BetPlaced(
        uint256 indexed betId,
        address indexed player,
        address indexed asset,
        Choice choice,
        uint256 wagerAmount,
        uint256 mattEquivalent,
        uint256 payoutAmount,
        uint256 burnAmount,
        uint256 entropyBlock,
        uint256 revealDeadlineBlock,
        bytes32 commitment
    );
    event GamePlayed(
        uint256 indexed betId,
        address indexed player,
        address indexed asset,
        uint256 wagerAmount,
        uint256 mattEquivalent,
        Choice choice,
        Choice outcome,
        bool won,
        bool expired,
        uint256 payoutAmount,
        uint256 burnAmount
    );
    event WinnerPaid(uint256 indexed betId, address indexed player, uint256 amount);
    event MattBurned(uint256 indexed betId, address indexed player, uint256 amount, bool expired);
    event TreasuryDeposit(
        uint256 indexed betId,
        address indexed player,
        address indexed asset,
        uint256 amount
    );
    event PoolPriceUsed(
        uint256 indexed betId,
        address indexed asset,
        address indexed pool,
        uint32 twapWindow,
        int24 arithmeticMeanTick,
        uint128 harmonicMeanLiquidity,
        uint256 mattEquivalent
    );
    event BetExpired(uint256 indexed betId, address indexed player);
    event AccidentalTokenWithdrawn(address indexed token, uint256 amount);
    event AccidentalRonWithdrawn(uint256 amount);

    constructor(
        address mattToken,
        address wrappedRonToken,
        address v3Factory,
        address payable treasurySafe,
        address initialRewardVault,
        address initialOwner
    ) Ownable(initialOwner) {
        if (
            mattToken == address(0) || wrappedRonToken == address(0)
                || v3Factory == address(0) || treasurySafe == address(0)
                || initialRewardVault == address(0) || initialOwner == address(0)
        ) revert ZeroAddress();
        matt = IERC20(mattToken);
        wrappedRon = wrappedRonToken;
        katanaV3Factory = v3Factory;
        treasury = treasurySafe;
        rewardVault = IMattRewardVault(initialRewardVault);
        _pause();
    }

    function commitmentFor(
        address player,
        address asset,
        Choice choice,
        uint256 amount,
        bytes32 secret
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                secret,
                player,
                asset,
                choice,
                amount,
                address(this),
                block.chainid
            )
        );
    }

    function quoteMatt(address asset, uint256 amount)
        public
        view
        returns (
            uint256 mattEquivalent,
            int24 arithmeticMeanTick,
            uint128 harmonicMeanLiquidity,
            address pool
        )
    {
        AssetConfig memory config = assetConfigs[asset];
        if (!config.supported) revert UnsupportedAsset(asset);
        if (amount == 0) revert InvalidWagerAmount();
        if (amount > type(uint128).max) revert WagerTooLarge(amount);

        if (asset == address(matt)) {
            return (amount, 0, 0, address(0));
        }

        pool = config.pool;
        (arithmeticMeanTick, harmonicMeanLiquidity) =
            KatanaTwap.consult(pool, TWAP_WINDOW);
        if (harmonicMeanLiquidity < config.minHarmonicLiquidity) {
            revert OracleLiquidityTooLow(
                harmonicMeanLiquidity,
                config.minHarmonicLiquidity
            );
        }
        address oracleToken = asset == NATIVE_RON ? wrappedRon : asset;
        mattEquivalent = KatanaTwap.getQuoteAtTick(
            arithmeticMeanTick,
            uint128(amount),
            oracleToken,
            address(matt)
        );
        if (mattEquivalent == 0) revert QuoteIsZero();
    }

    function placeBet(
        address asset,
        Choice choice,
        uint256 amount,
        bytes32 commitment
    ) external nonReentrant whenNotPaused returns (uint256 betId) {
        if (asset == NATIVE_RON) revert InvalidWagerAmount();
        betId = _placeBet(msg.sender, asset, choice, amount, commitment);
        uint256 beforeBalance = IERC20(asset).balanceOf(treasury);
        IERC20(asset).safeTransferFrom(msg.sender, treasury, amount);
        if (IERC20(asset).balanceOf(treasury) - beforeBalance != amount) {
            revert UnsupportedTokenBehavior();
        }
        emit TreasuryDeposit(betId, msg.sender, asset, amount);
    }

    function placeRonBet(Choice choice, bytes32 commitment)
        external
        payable
        nonReentrant
        whenNotPaused
        returns (uint256 betId)
    {
        betId = _placeBet(
            msg.sender,
            NATIVE_RON,
            choice,
            msg.value,
            commitment
        );
        (bool sent,) = treasury.call{value: msg.value}("");
        if (!sent) revert TreasuryTransferFailed();
        emit TreasuryDeposit(betId, msg.sender, NATIVE_RON, msg.value);
    }

    function revealAndSettle(uint256 betId, bytes32 secret)
        external
        nonReentrant
        returns (bool won)
    {
        Bet storage bet = bets[betId];
        if (bet.state != BetState.Pending) revert BetNotPending(betId);
        if (msg.sender != bet.player) {
            revert NotBetPlayer(msg.sender, bet.player);
        }
        if (block.number <= bet.entropyBlock) {
            revert EntropyBlockNotReady(
                block.number,
                uint256(bet.entropyBlock) + 1
            );
        }
        if (block.number > bet.revealDeadlineBlock) {
            revert RevealWindowClosed(block.number, bet.revealDeadlineBlock);
        }
        if (
            commitmentFor(
                msg.sender,
                bet.asset,
                bet.choice,
                bet.wagerAmount,
                secret
            ) != bet.commitment
        ) revert InvalidSecret();

        bytes32 entropyHash = blockhash(bet.entropyBlock);
        if (entropyHash == bytes32(0)) revert EntropyUnavailable();
        uint256 randomWord = uint256(
            keccak256(
                abi.encodePacked(
                    secret,
                    entropyHash,
                    betId,
                    address(this),
                    block.chainid
                )
            )
        );
        Choice outcome = Choice(uint8(randomWord & 1));
        won = outcome == bet.choice;
        _clearReservation(bet);
        bet.state = won ? BetState.Won : BetState.Lost;

        if (won) {
            rewardVault.payWinner(bet.player, bet.payoutAmount);
            totalMattPaid += bet.payoutAmount;
            emit WinnerPaid(betId, bet.player, bet.payoutAmount);
        } else {
            rewardVault.burnMatt(bet.burnAmount);
            totalMattBurned += bet.burnAmount;
            emit MattBurned(betId, bet.player, bet.burnAmount, false);
        }

        totalGames++;
        emit GamePlayed(
            betId,
            bet.player,
            bet.asset,
            bet.wagerAmount,
            bet.mattEquivalent,
            bet.choice,
            outcome,
            won,
            false,
            bet.payoutAmount,
            bet.burnAmount
        );
    }

    function expireBet(uint256 betId) external nonReentrant {
        Bet storage bet = bets[betId];
        if (bet.state != BetState.Pending) revert BetNotPending(betId);
        if (block.number <= bet.revealDeadlineBlock) {
            revert RevealWindowStillOpen(
                block.number,
                uint256(bet.revealDeadlineBlock) + 1
            );
        }
        _clearReservation(bet);
        bet.state = BetState.Expired;
        rewardVault.burnMatt(bet.burnAmount);
        totalMattBurned += bet.burnAmount;
        totalGames++;

        emit MattBurned(betId, bet.player, bet.burnAmount, true);
        emit GamePlayed(
            betId,
            bet.player,
            bet.asset,
            bet.wagerAmount,
            bet.mattEquivalent,
            bet.choice,
            Choice(uint8(1) - uint8(bet.choice)),
            false,
            true,
            bet.payoutAmount,
            bet.burnAmount
        );
        emit BetExpired(betId, bet.player);
    }

    function addSupportedAsset(
        address asset,
        address pool,
        uint128 minHarmonicLiquidity
    ) external onlyOwner whenPaused {
        if (assetConfigs[asset].supported) {
            revert AssetAlreadySupported(asset);
        }
        _setAsset(asset, pool, minHarmonicLiquidity);
        emit SupportedAssetAdded(asset, pool, minHarmonicLiquidity);
    }

    function removeSupportedAsset(address asset) external onlyOwner whenPaused {
        if (!assetConfigs[asset].supported) revert UnsupportedAsset(asset);
        delete assetConfigs[asset];
        emit SupportedAssetRemoved(asset);
    }

    function updateV3Pool(
        address asset,
        address newPool,
        uint128 minHarmonicLiquidity
    ) external onlyOwner whenPaused {
        AssetConfig memory current = assetConfigs[asset];
        if (!current.supported) revert UnsupportedAsset(asset);
        _setAsset(asset, newPool, minHarmonicLiquidity);
        emit V3PoolUpdated(
            asset,
            current.pool,
            newPool,
            minHarmonicLiquidity
        );
    }

    function configureRewardVault(address newVault)
        external
        onlyOwner
        whenPaused
    {
        if (newVault == address(0)) revert ZeroAddress();
        if (reservedPayouts != 0) {
            revert OutstandingPayoutReservations(reservedPayouts);
        }
        address previous = address(rewardVault);
        rewardVault = IMattRewardVault(newVault);
        emit RewardVaultConfigured(previous, newVault);
    }

    function configureBurnBps(uint16 newBurnBps) external onlyOwner whenPaused {
        if (newBurnBps > BPS) revert InvalidBasisPoints(newBurnBps);
        uint16 previous = burnBps;
        burnBps = newBurnBps;
        emit BurnBpsConfigured(previous, newBurnBps);
    }

    function configurePayoutMultiplier(uint32 newMultiplierBps)
        external
        onlyOwner
        whenPaused
    {
        if (newMultiplierBps < BPS || newMultiplierBps > 100_000) {
            revert InvalidPayoutMultiplier(newMultiplierBps);
        }
        uint32 previous = payoutMultiplierBps;
        payoutMultiplierBps = newMultiplierBps;
        emit PayoutMultiplierConfigured(previous, newMultiplierBps);
    }

    function availableRewardBalance() public view returns (uint256) {
        uint256 balance = matt.balanceOf(address(rewardVault));
        return balance > reservedPayouts ? balance - reservedPayouts : 0;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        if (rewardVault.paused()) revert RewardVaultPaused();
        _unpause();
    }

    function emergencyWithdrawAccidentalToken(address token, uint256 amount)
        external
        onlyOwner
        whenPaused
        nonReentrant
    {
        if (token == address(0)) revert ZeroAddress();
        IERC20(token).safeTransfer(treasury, amount);
        emit AccidentalTokenWithdrawn(token, amount);
    }

    function emergencyWithdrawAccidentalRon(uint256 amount)
        external
        onlyOwner
        whenPaused
        nonReentrant
    {
        (bool sent,) = treasury.call{value: amount}("");
        if (!sent) revert TreasuryTransferFailed();
        emit AccidentalRonWithdrawn(amount);
    }

    function _placeBet(
        address player,
        address asset,
        Choice choice,
        uint256 amount,
        bytes32 commitment
    ) private returns (uint256 betId) {
        if (amount == 0) revert InvalidWagerAmount();
        uint256 current = activeBetOf[player];
        if (current != 0) revert ActiveBetExists(current);

        (
            uint256 mattEquivalent,
            int24 meanTick,
            uint128 harmonicLiquidity,
            address pool
        ) = quoteMatt(asset, amount);
        uint256 payoutAmount =
            mattEquivalent * payoutMultiplierBps / BPS;
        uint256 burnAmount = mattEquivalent * burnBps / BPS;
        uint256 required = reservedPayouts + payoutAmount;
        uint256 vaultBalance = matt.balanceOf(address(rewardVault));
        if (vaultBalance < required) {
            revert InsufficientRewardVault(vaultBalance, required);
        }
        if (rewardVault.paused()) revert RewardVaultPaused();

        betId = nextBetId++;
        uint64 entropyBlock = uint64(block.number + ENTROPY_DELAY_BLOCKS);
        uint64 deadline = entropyBlock + REVEAL_WINDOW_BLOCKS;
        bets[betId] = Bet({
            player: player,
            asset: asset,
            wagerAmount: amount,
            mattEquivalent: mattEquivalent,
            payoutAmount: payoutAmount,
            burnAmount: burnAmount,
            entropyBlock: entropyBlock,
            revealDeadlineBlock: deadline,
            meanTick: meanTick,
            choice: choice,
            state: BetState.Pending,
            commitment: commitment
        });
        activeBetOf[player] = betId;
        reservedPayouts = required;

        emit PoolPriceUsed(
            betId,
            asset,
            pool,
            asset == address(matt) ? 0 : TWAP_WINDOW,
            meanTick,
            harmonicLiquidity,
            mattEquivalent
        );
        emit BetPlaced(
            betId,
            player,
            asset,
            choice,
            amount,
            mattEquivalent,
            payoutAmount,
            burnAmount,
            entropyBlock,
            deadline,
            commitment
        );
    }

    function _clearReservation(Bet storage bet) private {
        activeBetOf[bet.player] = 0;
        reservedPayouts -= bet.payoutAmount;
    }

    function _setAsset(
        address asset,
        address pool,
        uint128 minHarmonicLiquidity
    ) private {
        if (asset == address(matt)) {
            if (pool != address(0) || minHarmonicLiquidity != 0) {
                revert InvalidMattIdentityConfiguration(
                    pool,
                    minHarmonicLiquidity
                );
            }
            assetConfigs[asset] = AssetConfig({
                pool: address(0),
                minHarmonicLiquidity: 0,
                supported: true
            });
            return;
        }

        if (pool == address(0) || pool.code.length == 0) {
            revert InvalidPool(pool);
        }
        if (minHarmonicLiquidity == 0) {
            revert InvalidMinimumLiquidity();
        }
        address oracleToken = asset == NATIVE_RON ? wrappedRon : asset;

        IKatanaV3Pool katanaPool = IKatanaV3Pool(pool);
        address actualFactory = katanaPool.factory();
        if (actualFactory != katanaV3Factory) {
            revert InvalidPoolFactory(katanaV3Factory, actualFactory);
        }
        address token0 = katanaPool.token0();
        address token1 = katanaPool.token1();
        bool validPair = (token0 == oracleToken && token1 == address(matt))
            || (token0 == address(matt) && token1 == oracleToken);
        if (!validPair) revert InvalidPoolPair(token0, token1);
        if (katanaPool.liquidity() == 0) revert PoolHasNoLiquidity(pool);

        katanaPool.increaseObservationCardinalityNext(
            TARGET_OBSERVATION_CARDINALITY
        );
        assetConfigs[asset] = AssetConfig({
            pool: pool,
            minHarmonicLiquidity: minHarmonicLiquidity,
            supported: true
        });
    }
}

contracts/MattRewardVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IMattBurnable is IERC20 {
    function burn(uint256 amount) external;
}

/// @title MATT BurnFlip Reward Vault
/// @notice Holds only MATT and exposes narrowly scoped pay and burn operations to BurnFlip.
contract MattRewardVault is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    error ZeroAddress();
    error UnauthorizedBurnFlip(address caller);
    error BurnFlipNotConfigured();
    error CannotRescueMatt();
    error InsufficientMatt(uint256 available, uint256 required);

    IMattBurnable public immutable matt;
    address public burnFlip;
    uint256 public totalPaid;
    uint256 public totalBurned;

    event BurnFlipConfigured(address indexed previousBurnFlip, address indexed newBurnFlip);
    event MattDeposited(address indexed depositor, uint256 amount);
    event WinnerPaid(address indexed winner, uint256 amount);
    event MattBurned(uint256 amount);
    event AccidentalTokenRescued(address indexed token, address indexed recipient, uint256 amount);

    modifier onlyBurnFlip() {
        if (msg.sender != burnFlip || burnFlip == address(0)) {
            revert UnauthorizedBurnFlip(msg.sender);
        }
        _;
    }

    constructor(address mattToken, address initialOwner) Ownable(initialOwner) {
        if (mattToken == address(0) || initialOwner == address(0)) revert ZeroAddress();
        matt = IMattBurnable(mattToken);
        _pause();
    }

    function configureBurnFlip(address newBurnFlip) external onlyOwner whenPaused {
        if (newBurnFlip == address(0)) revert ZeroAddress();
        address previous = burnFlip;
        burnFlip = newBurnFlip;
        emit BurnFlipConfigured(previous, newBurnFlip);
    }

    function depositMatt(uint256 amount) external nonReentrant {
        _deposit(msg.sender, amount);
    }

    function ownerRefill(uint256 amount) external onlyOwner nonReentrant {
        _deposit(msg.sender, amount);
    }

    function payWinner(address winner, uint256 amount)
        external
        onlyBurnFlip
        whenNotPaused
        nonReentrant
    {
        if (winner == address(0)) revert ZeroAddress();
        _requireBalance(amount);
        totalPaid += amount;
        IERC20(address(matt)).safeTransfer(winner, amount);
        emit WinnerPaid(winner, amount);
    }

    function burnMatt(uint256 amount)
        external
        onlyBurnFlip
        whenNotPaused
        nonReentrant
    {
        _requireBalance(amount);
        totalBurned += amount;
        matt.burn(amount);
        emit MattBurned(amount);
    }

    function mattBalance() external view returns (uint256) {
        return matt.balanceOf(address(this));
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        if (burnFlip == address(0)) revert BurnFlipNotConfigured();
        _unpause();
    }

    function rescueAccidentalToken(address token, uint256 amount)
        external
        onlyOwner
        whenPaused
        nonReentrant
    {
        if (token == address(0)) revert ZeroAddress();
        if (token == address(matt)) revert CannotRescueMatt();
        address recipient = owner();
        IERC20(token).safeTransfer(recipient, amount);
        emit AccidentalTokenRescued(token, recipient, amount);
    }

    function _deposit(address depositor, uint256 amount) private {
        uint256 beforeBalance = matt.balanceOf(address(this));
        IERC20(address(matt)).safeTransferFrom(depositor, address(this), amount);
        uint256 received = matt.balanceOf(address(this)) - beforeBalance;
        if (received != amount) revert InsufficientMatt(received, amount);
        emit MattDeposited(depositor, amount);
    }

    function _requireBalance(uint256 amount) private view {
        uint256 balance = matt.balanceOf(address(this));
        if (balance < amount) revert InsufficientMatt(balance, amount);
    }
}

contracts/MattSlotsRewardVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IMattSlotsTreasuryConverter {
    function recordLoss(uint256 amount) external;
}

/// @title MATT Slots Reward Vault
/// @notice Protects prepaid spin principal, player winnings, bonus-session liability,
///         and settled MATT waiting to be sent to the RON converter.
contract MattSlotsRewardVault is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint8 private constant STATUS_PENDING = 1;
    uint8 private constant STATUS_SETTLED = 2;
    uint8 private constant STATUS_CANCELLED = 3;
    uint8 private constant SESSION_ACTIVE = 1;
    uint8 private constant SESSION_COMPLETE = 2;

    struct PaidReservation {
        address recipient;
        uint256 principal;
        uint256 maximumPayout;
        uint256 reservedAmount;
        uint8 status;
    }

    struct BonusReservation {
        address recipient;
        uint256 remainingLiability;
        uint8 status;
    }

    IERC20 public immutable matt;
    IMattSlotsTreasuryConverter public immutable converter;
    address public controller;

    uint256 public totalReserved;
    uint256 public totalClaimable;
    uint256 public pendingTreasuryLoss;
    uint256 public totalTreasuryLossSettled;
    uint256 public totalTreasuryLossFlushed;

    mapping(uint256 spinId => PaidReservation reservation) public paidReservations;
    mapping(uint256 sessionId => BonusReservation reservation) public bonusReservations;
    mapping(address recipient => uint256 amount) public claimable;

    event ControllerUpdated(address indexed previousController, address indexed newController);
    event BankrollFunded(address indexed owner, uint256 amount);
    event BankrollWithdrawn(address indexed owner, uint256 amount);
    event PaidSpinReserved(
        uint256 indexed spinId,
        address indexed recipient,
        uint256 principal,
        uint256 maximumPayout
    );
    event PaidSpinSettled(
        uint256 indexed spinId,
        address indexed recipient,
        uint256 payout,
        uint256 treasuryLoss,
        uint256 indexed bonusSessionId,
        uint256 carriedLiability
    );
    event PaidSpinCancelled(uint256 indexed spinId, address indexed recipient, uint256 principal);
    event BonusSpinSettled(
        uint256 indexed spinId,
        uint256 indexed sessionId,
        address indexed recipient,
        uint256 payout,
        uint256 remainingLiability,
        bool sessionComplete
    );
    event BonusSessionForfeited(uint256 indexed sessionId, address indexed recipient, uint256 released);
    event TreasuryLossFlushed(uint256 amount, uint256 remainingPending);
    event PayoutClaimed(address indexed recipient, uint256 amount);

    error Unauthorized();
    error InvalidAddress();
    error InvalidAmount();
    error InvalidReservation();
    error InsufficientBankroll(uint256 available, uint256 required);
    error MattLocked();
    error UnsupportedToken();

    constructor(address mattToken, address converterAddress, address initialOwner)
        Ownable(initialOwner)
    {
        if (
            mattToken == address(0) || converterAddress == address(0)
                || initialOwner == address(0)
        ) revert InvalidAddress();
        if (converterAddress.code.length == 0) revert InvalidAddress();
        matt = IERC20(mattToken);
        converter = IMattSlotsTreasuryConverter(converterAddress);
    }

    modifier onlyController() {
        if (msg.sender != controller) revert Unauthorized();
        _;
    }

    function setController(address newController) external onlyOwner {
        if (newController == address(0) || newController.code.length == 0) {
            revert InvalidAddress();
        }
        if (totalReserved != 0) revert InvalidReservation();
        address previous = controller;
        controller = newController;
        emit ControllerUpdated(previous, newController);
    }

    /// @notice Pulls one paid spin's principal from the controller and protects it
    /// independently while reserving the complete 500x session payout liability.
    function reservePaid(
        uint256 spinId,
        address recipient,
        uint256 principal,
        uint256 maximumPayout
    ) external onlyController nonReentrant {
        if (
            recipient == address(0) || principal == 0 || maximumPayout < principal
                || paidReservations[spinId].status != 0
        ) revert InvalidReservation();

        uint256 beforeBalance = matt.balanceOf(address(this));
        matt.safeTransferFrom(msg.sender, address(this), principal);
        uint256 received = matt.balanceOf(address(this)) - beforeBalance;
        if (received != principal) revert InvalidAmount();

        uint256 reservedAmount = maximumPayout + principal;
        uint256 available = availableBankroll();
        if (available < reservedAmount) {
            revert InsufficientBankroll(available, reservedAmount);
        }

        paidReservations[spinId] = PaidReservation({
            recipient: recipient,
            principal: principal,
            maximumPayout: maximumPayout,
            reservedAmount: reservedAmount,
            status: STATUS_PENDING
        });
        totalReserved += reservedAmount;
        emit PaidSpinReserved(spinId, recipient, principal, maximumPayout);
    }

    /// @notice Settles the paid/root spin. When it starts free spins, the unused part
    /// of the already-reserved 500x cap is carried into a persistent bonus reservation.
    function settlePaid(
        uint256 spinId,
        uint256 payout,
        uint256 bonusSessionId,
        bool carryBonusLiability
    ) external onlyController {
        PaidReservation storage reservation = paidReservations[spinId];
        if (
            reservation.status != STATUS_PENDING
                || payout > reservation.maximumPayout
                || (carryBonusLiability && bonusSessionId == 0)
                || (!carryBonusLiability && bonusSessionId != 0)
        ) revert InvalidReservation();

        reservation.status = STATUS_SETTLED;
        totalReserved -= reservation.reservedAmount;

        if (payout != 0) {
            totalClaimable += payout;
            claimable[reservation.recipient] += payout;
        }

        uint256 treasuryLoss = reservation.principal > payout
            ? reservation.principal - payout
            : 0;
        if (treasuryLoss != 0) {
            pendingTreasuryLoss += treasuryLoss;
            totalTreasuryLossSettled += treasuryLoss;
        }

        uint256 carriedLiability;
        if (carryBonusLiability) {
            if (bonusReservations[bonusSessionId].status != 0) revert InvalidReservation();
            carriedLiability = reservation.maximumPayout - payout;
            if (carriedLiability == 0) revert InvalidReservation();
            bonusReservations[bonusSessionId] = BonusReservation({
                recipient: reservation.recipient,
                remainingLiability: carriedLiability,
                status: SESSION_ACTIVE
            });
            totalReserved += carriedLiability;
        }

        emit PaidSpinSettled(
            spinId,
            reservation.recipient,
            payout,
            treasuryLoss,
            bonusSessionId,
            carriedLiability
        );
    }

    /// @notice Applies one free-spin payout against the persistent session cap.
    function settleBonus(
        uint256 spinId,
        uint256 sessionId,
        uint256 payout,
        bool sessionComplete
    ) external onlyController {
        BonusReservation storage reservation = bonusReservations[sessionId];
        if (
            reservation.status != SESSION_ACTIVE
                || payout > reservation.remainingLiability
        ) revert InvalidReservation();

        if (payout != 0) {
            reservation.remainingLiability -= payout;
            totalReserved -= payout;
            totalClaimable += payout;
            claimable[reservation.recipient] += payout;
        }

        uint256 released;
        if (sessionComplete) {
            released = reservation.remainingLiability;
            if (released != 0) totalReserved -= released;
            reservation.remainingLiability = 0;
            reservation.status = SESSION_COMPLETE;
        }

        emit BonusSpinSettled(
            spinId,
            sessionId,
            reservation.recipient,
            payout,
            reservation.remainingLiability,
            sessionComplete
        );
    }

    function cancelPaid(uint256 spinId) external onlyController nonReentrant {
        PaidReservation storage reservation = paidReservations[spinId];
        if (reservation.status != STATUS_PENDING) revert InvalidReservation();
        reservation.status = STATUS_CANCELLED;
        totalReserved -= reservation.reservedAmount;
        matt.safeTransfer(msg.sender, reservation.principal);
        emit PaidSpinCancelled(spinId, reservation.recipient, reservation.principal);
    }

    /// @notice A player may voluntarily surrender unused free spins so the unspent
    /// liability can be unlocked. No paid principal is involved in a bonus session.
    function forfeitBonusSession(uint256 sessionId, address recipient)
        external
        onlyController
    {
        BonusReservation storage reservation = bonusReservations[sessionId];
        if (
            reservation.status != SESSION_ACTIVE || reservation.recipient != recipient
        ) revert InvalidReservation();
        uint256 released = reservation.remainingLiability;
        reservation.remainingLiability = 0;
        reservation.status = SESSION_COMPLETE;
        totalReserved -= released;
        emit BonusSessionForfeited(sessionId, recipient, released);
    }

    function flushTreasuryLoss(uint256 amount) external nonReentrant {
        if (amount == 0 || amount > pendingTreasuryLoss) revert InvalidAmount();
        pendingTreasuryLoss -= amount;
        totalTreasuryLossFlushed += amount;
        matt.safeTransfer(address(converter), amount);
        converter.recordLoss(amount);
        emit TreasuryLossFlushed(amount, pendingTreasuryLoss);
    }

    function claim() external nonReentrant {
        uint256 amount = claimable[msg.sender];
        if (amount == 0) revert InvalidAmount();
        claimable[msg.sender] = 0;
        totalClaimable -= amount;
        matt.safeTransfer(msg.sender, amount);
        emit PayoutClaimed(msg.sender, amount);
    }

    function fund(uint256 amount) external onlyOwner nonReentrant {
        if (amount == 0) revert InvalidAmount();
        uint256 beforeBalance = matt.balanceOf(address(this));
        matt.safeTransferFrom(msg.sender, address(this), amount);
        if (matt.balanceOf(address(this)) - beforeBalance != amount) revert InvalidAmount();
        emit BankrollFunded(msg.sender, amount);
    }

    function withdrawAvailable(uint256 amount) external onlyOwner nonReentrant {
        uint256 available = availableBankroll();
        if (amount == 0 || amount > available) {
            revert InsufficientBankroll(available, amount);
        }
        matt.safeTransfer(owner(), amount);
        emit BankrollWithdrawn(owner(), amount);
    }

    function protectedBalance() public view returns (uint256) {
        return totalReserved + totalClaimable + pendingTreasuryLoss;
    }

    function availableBankroll() public view returns (uint256) {
        uint256 balance = matt.balanceOf(address(this));
        uint256 locked = protectedBalance();
        return balance > locked ? balance - locked : 0;
    }

    function isSolvent() external view returns (bool) {
        return matt.balanceOf(address(this)) >= protectedBalance();
    }

    function recoverUnsupportedToken(address token, uint256 amount)
        external
        onlyOwner
        nonReentrant
    {
        if (token == address(matt)) revert MattLocked();
        if (token == address(0) || amount == 0) revert InvalidAmount();
        IERC20(token).safeTransfer(owner(), amount);
    }
}

contracts/MattSlotsTreasuryConverter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IKatanaV3Pool} from "./interfaces/IKatanaV3Pool.sol";
import {KatanaTwap} from "./libraries/KatanaTwap.sol";

interface IWrappedRonForSlots is IERC20 {
    function withdraw(uint256 amount) external;
}

/// @title MATT Slots Treasury Converter
/// @notice Holds settled net-losing MATT, swaps it into WRON through an approved router,
///         unwraps it, and forwards every resulting RON to the immutable treasury.
/// @dev The caller supplies router calldata, but settlement is protected by an exact MATT
///      allowance, balance-delta checks, a 30-minute Katana TWAP floor, and a fixed recipient.
contract MattSlotsTreasuryConverter is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant BPS = 10_000;
    uint32 public constant TWAP_WINDOW = 30 minutes;
    uint16 public constant MAX_CONFIGURABLE_SLIPPAGE_BPS = 1_500;

    IERC20 public immutable matt;
    IWrappedRonForSlots public immutable wrappedRon;
    address public immutable katanaV3Factory;
    address public immutable pool;
    address payable public immutable treasury;

    address public sourceVault;
    address public router;
    address public keeper;
    uint16 public maxSlippageBps;
    uint128 public minHarmonicLiquidity;

    uint256 public pendingMatt;
    uint256 public totalMattReceived;
    uint256 public totalMattConverted;
    uint256 public totalRonForwarded;

    event SourceVaultConfigured(address indexed sourceVault);
    event RouterConfigured(address indexed previousRouter, address indexed newRouter);
    event KeeperConfigured(address indexed previousKeeper, address indexed newKeeper);
    event ConversionProtectionConfigured(
        uint16 previousMaxSlippageBps,
        uint16 newMaxSlippageBps,
        uint128 previousMinHarmonicLiquidity,
        uint128 newMinHarmonicLiquidity
    );
    event LossRecorded(uint256 amount, uint256 pendingMatt);
    event MattConverted(
        address indexed caller,
        address indexed router,
        uint256 mattIn,
        uint256 ronOut,
        uint256 twapQuote,
        uint256 minimumOut
    );
    event AccidentalRonForwarded(uint256 amount);

    error Unauthorized();
    error InvalidAddress();
    error InvalidAmount();
    error InvalidPool();
    error InvalidPoolFactory(address expected, address actual);
    error InvalidPoolPair(address token0, address token1);
    error PoolHasNoLiquidity();
    error InvalidBasisPoints(uint256 value);
    error SourceVaultAlreadyConfigured();
    error UnbackedLoss(uint256 available, uint256 required);
    error InsufficientPendingMatt(uint256 available, uint256 requested);
    error OracleLiquidityTooLow(uint128 actual, uint128 minimum);
    error MinimumOutputTooLow(uint256 provided, uint256 required);
    error SwapFailed(bytes reason);
    error UnexpectedMattSpent(uint256 expected, uint256 actual);
    error InsufficientWrappedRon(uint256 minimum, uint256 actual);
    error RonTransferFailed();
    error UnsupportedToken();

    constructor(
        address mattToken,
        address wrappedRonToken,
        address v3Factory,
        address v3Pool,
        address payable treasurySafe,
        address initialRouter,
        address initialKeeper,
        uint16 initialMaxSlippageBps,
        uint128 initialMinHarmonicLiquidity,
        address initialOwner
    ) Ownable(initialOwner) {
        if (
            mattToken == address(0) || wrappedRonToken == address(0)
                || v3Factory == address(0) || v3Pool == address(0)
                || treasurySafe == address(0) || initialRouter == address(0)
                || initialOwner == address(0)
        ) revert InvalidAddress();
        if (initialRouter.code.length == 0) revert InvalidAddress();
        if (initialMaxSlippageBps > MAX_CONFIGURABLE_SLIPPAGE_BPS) {
            revert InvalidBasisPoints(initialMaxSlippageBps);
        }
        if (initialMinHarmonicLiquidity == 0) revert InvalidAmount();

        IKatanaV3Pool configuredPool = IKatanaV3Pool(v3Pool);
        address actualFactory = configuredPool.factory();
        if (actualFactory != v3Factory) revert InvalidPoolFactory(v3Factory, actualFactory);
        address token0 = configuredPool.token0();
        address token1 = configuredPool.token1();
        if (
            !(
                (token0 == mattToken && token1 == wrappedRonToken)
                    || (token0 == wrappedRonToken && token1 == mattToken)
            )
        ) revert InvalidPoolPair(token0, token1);
        if (configuredPool.liquidity() == 0) revert PoolHasNoLiquidity();

        matt = IERC20(mattToken);
        wrappedRon = IWrappedRonForSlots(wrappedRonToken);
        katanaV3Factory = v3Factory;
        pool = v3Pool;
        treasury = treasurySafe;
        router = initialRouter;
        keeper = initialKeeper;
        maxSlippageBps = initialMaxSlippageBps;
        minHarmonicLiquidity = initialMinHarmonicLiquidity;
        _pause();
    }

    modifier onlySourceVault() {
        if (msg.sender != sourceVault) revert Unauthorized();
        _;
    }

    modifier onlyKeeperOrOwner() {
        if (msg.sender != keeper && msg.sender != owner()) revert Unauthorized();
        _;
    }

    function configureSourceVault(address vault) external onlyOwner {
        if (sourceVault != address(0)) revert SourceVaultAlreadyConfigured();
        if (vault == address(0) || vault.code.length == 0) revert InvalidAddress();
        sourceVault = vault;
        emit SourceVaultConfigured(vault);
    }

    /// @notice Called after the source vault has transferred the same amount of MATT here.
    function recordLoss(uint256 amount) external onlySourceVault {
        if (amount == 0) revert InvalidAmount();
        uint256 requiredBalance = pendingMatt + amount;
        uint256 balance = matt.balanceOf(address(this));
        if (balance < requiredBalance) revert UnbackedLoss(balance, requiredBalance);
        pendingMatt = requiredBalance;
        totalMattReceived += amount;
        emit LossRecorded(amount, requiredBalance);
    }

    /// @notice Converts queued MATT through the approved router and forwards native RON.
    /// @param routerCall Calldata that must spend exactly amountIn MATT and deliver WRON here.
    function convert(
        uint256 amountIn,
        uint256 amountOutMinimum,
        bytes calldata routerCall
    ) external whenNotPaused nonReentrant onlyKeeperOrOwner returns (uint256 ronOut) {
        if (amountIn == 0 || amountIn > type(uint128).max || routerCall.length < 4) {
            revert InvalidAmount();
        }
        if (amountIn > pendingMatt) revert InsufficientPendingMatt(pendingMatt, amountIn);

        (uint256 twapQuote, uint128 harmonicLiquidity) = quoteTwap(amountIn);
        if (harmonicLiquidity < minHarmonicLiquidity) {
            revert OracleLiquidityTooLow(harmonicLiquidity, minHarmonicLiquidity);
        }
        uint256 requiredMinimum = Math.mulDiv(
            twapQuote,
            BPS - maxSlippageBps,
            BPS
        );
        if (amountOutMinimum < requiredMinimum) {
            revert MinimumOutputTooLow(amountOutMinimum, requiredMinimum);
        }

        uint256 mattBefore = matt.balanceOf(address(this));
        uint256 wronBefore = wrappedRon.balanceOf(address(this));
        matt.forceApprove(router, amountIn);
        (bool success, bytes memory reason) = router.call(routerCall);
        if (!success) revert SwapFailed(reason);
        matt.forceApprove(router, 0);

        uint256 mattAfter = matt.balanceOf(address(this));
        uint256 spent = mattBefore > mattAfter ? mattBefore - mattAfter : 0;
        if (spent != amountIn) revert UnexpectedMattSpent(amountIn, spent);

        uint256 wronAfter = wrappedRon.balanceOf(address(this));
        ronOut = wronAfter > wronBefore ? wronAfter - wronBefore : 0;
        if (ronOut < amountOutMinimum) {
            revert InsufficientWrappedRon(amountOutMinimum, ronOut);
        }

        pendingMatt -= amountIn;
        totalMattConverted += amountIn;
        totalRonForwarded += ronOut;

        wrappedRon.withdraw(ronOut);
        (bool sent,) = treasury.call{value: ronOut}("");
        if (!sent) revert RonTransferFailed();

        emit MattConverted(
            msg.sender,
            router,
            amountIn,
            ronOut,
            twapQuote,
            amountOutMinimum
        );
    }

    function quoteTwap(uint256 amountIn)
        public
        view
        returns (uint256 wrappedRonOut, uint128 harmonicLiquidity)
    {
        if (amountIn == 0 || amountIn > type(uint128).max) revert InvalidAmount();
        (int24 meanTick, uint128 liquidity) = KatanaTwap.consult(pool, TWAP_WINDOW);
        wrappedRonOut = KatanaTwap.getQuoteAtTick(
            meanTick,
            uint128(amountIn),
            address(matt),
            address(wrappedRon)
        );
        if (wrappedRonOut == 0) revert InvalidAmount();
        harmonicLiquidity = liquidity;
    }

    function setRouter(address newRouter) external onlyOwner whenPaused {
        if (newRouter == address(0) || newRouter.code.length == 0) revert InvalidAddress();
        address previous = router;
        router = newRouter;
        emit RouterConfigured(previous, newRouter);
    }

    function setKeeper(address newKeeper) external onlyOwner {
        address previous = keeper;
        keeper = newKeeper;
        emit KeeperConfigured(previous, newKeeper);
    }

    function setConversionProtection(
        uint16 newMaxSlippageBps,
        uint128 newMinHarmonicLiquidity
    ) external onlyOwner whenPaused {
        if (newMaxSlippageBps > MAX_CONFIGURABLE_SLIPPAGE_BPS) {
            revert InvalidBasisPoints(newMaxSlippageBps);
        }
        if (newMinHarmonicLiquidity == 0) revert InvalidAmount();
        uint16 previousSlippage = maxSlippageBps;
        uint128 previousLiquidity = minHarmonicLiquidity;
        maxSlippageBps = newMaxSlippageBps;
        minHarmonicLiquidity = newMinHarmonicLiquidity;
        emit ConversionProtectionConfigured(
            previousSlippage,
            newMaxSlippageBps,
            previousLiquidity,
            newMinHarmonicLiquidity
        );
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        if (sourceVault == address(0)) revert InvalidAddress();
        _unpause();
    }

    function forwardAccidentalRon() external onlyOwner nonReentrant {
        uint256 amount = address(this).balance;
        if (amount == 0) revert InvalidAmount();
        (bool sent,) = treasury.call{value: amount}("");
        if (!sent) revert RonTransferFailed();
        emit AccidentalRonForwarded(amount);
    }

    function recoverUnsupportedToken(address token, uint256 amount)
        external
        onlyOwner
        nonReentrant
    {
        if (token == address(matt) || token == address(wrappedRon)) revert UnsupportedToken();
        if (token == address(0) || amount == 0) revert InvalidAmount();
        IERC20(token).safeTransfer(treasury, amount);
    }

    receive() external payable {
        if (msg.sender != address(wrappedRon)) revert Unauthorized();
    }
}

contracts/MattSlotsV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

interface IRoninVRFCoordinatorForMattSlots {
    function requestRandomSeed(
        uint256 callbackGasLimit,
        uint256 gasPrice,
        address consumer,
        address refundAddress
    ) external payable returns (bytes32 requestHash);

    function estimateRequestRandomFee(uint256 callbackGasLimit, uint256 gasPrice)
        external
        view
        returns (uint256);
}

interface IMattSlotsRewardVault {
    function reservePaid(
        uint256 spinId,
        address recipient,
        uint256 principal,
        uint256 maximumPayout
    ) external;

    function settlePaid(
        uint256 spinId,
        uint256 payout,
        uint256 bonusSessionId,
        bool carryBonusLiability
    ) external;

    function settleBonus(
        uint256 spinId,
        uint256 sessionId,
        uint256 payout,
        bool sessionComplete
    ) external;

    function cancelPaid(uint256 spinId) external;
    function forfeitBonusSession(uint256 sessionId, address recipient) external;
    function availableBankroll() external view returns (uint256);
    function claimable(address recipient) external view returns (uint256);
    function pendingTreasuryLoss() external view returns (uint256);
}

/// @title MATT Slots V1 — Resource Rush
/// @notice Five-reel, three-row, twenty-payline MATT slots with prepaid spin credits,
///         one Ronin VRF request per click, onchain reel grids, and onchain payouts.
/// @dev Every paid spin reserves the complete 500x session cap before randomness is
///      requested. Triggered free spins inherit that reservation and the root wager.
contract MattSlotsV1 is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant BPS = 10_000;
    uint256 public constant MAX_MULTIPLIER_BPS = 5_000_000; // 500x
    uint256 public constant CALLBACK_GAS_LIMIT = 1_000_000;
    uint256 public constant STALE_REQUEST_DELAY = 2 hours;
    uint256 public constant MATH_CONFIG_DELAY = 24 hours;
    uint8 public constant REELS = 5;
    uint8 public constant ROWS = 3;
    uint8 public constant PAYLINES = 20;
    uint8 public constant SYMBOL_COUNT = 10;
    uint8 public constant WILD_SYMBOL = 8;
    uint8 public constant SCATTER_SYMBOL = 9;
    uint8 public constant MIN_SPINS_PER_PURCHASE = 1;
    uint8 public constant MAX_SPINS_PER_PURCHASE = 25;
    uint8 public constant MAX_BONUS_SPINS = 50;

    uint8 private constant CREDIT_PAID = 1;
    uint8 private constant CREDIT_BONUS = 2;
    uint8 private constant SPIN_PENDING = 1;
    uint8 private constant SPIN_SETTLED = 2;
    uint8 private constant SPIN_REFUNDED = 3;
    uint8 private constant NO_WILD_REEL = type(uint8).max;

    // Each payline uses two bits per reel and ten bits total. Twenty lines fit in 200 bits.
    uint256 private constant PACKED_PAYLINES =
        0x2a22222165516661111964656151a94041aa4246192aa00155;

    struct MathConfig {
        uint256[5] reels;
        uint32[30] linePaysBps;
        uint32[3] scatterPaysBps;
        uint8[3] bonusAwards;
        uint16 declaredRtpBps;
        uint64 activatesAt;
        bool exists;
    }

    struct CreditBatch {
        uint96 wager;
        uint32 remaining;
        uint32 purchased;
        uint32 mathVersion;
        uint64 purchasedAt;
    }

    struct BonusSession {
        address player;
        uint96 wager;
        uint32 remaining;
        uint32 totalAwarded;
        uint32 totalPlayed;
        uint32 mathVersion;
        uint64 rootSpinId;
        uint256 totalPayout;
        bool completed;
    }

    struct Spin {
        address player;
        uint96 wager;
        uint64 requestedAt;
        uint64 previousPlayerSpinId;
        uint32 mathVersion;
        uint32 creditIndex;
        uint8 creditType;
        uint8 status;
        uint8 wildReel;
        uint8 scatterCount;
        uint8 freeSpinsAwarded;
        uint32 winningLinesMask;
        uint64 packedGrid;
        uint256 sessionId;
        uint256 payout;
        uint256 treasuryLoss;
        bytes32 requestHash;
    }

    IERC20 public immutable matt;
    IMattSlotsRewardVault public immutable rewardVault;
    IRoninVRFCoordinatorForMattSlots public immutable vrfCoordinator;

    uint256 public minBet = 500 ether;
    uint256 public maxBet = 50_000 ether;
    uint256 public nextSpinId = 1;
    uint256 public nextSessionId = 1;
    uint32 public activeMathVersion = 1;
    uint32 public pendingMathVersion;
    uint32 public latestMathVersion = 1;

    uint256 public totalCreditEscrow;
    uint256 public totalSpinsPurchased;
    uint256 public totalPaidSpinsPlayed;
    uint256 public totalBonusSpinsPlayed;
    uint256 public totalWagered;
    uint256 public totalPaid;
    uint256 public totalTreasuryLoss;

    mapping(uint32 version => MathConfig config) private mathConfigs;
    mapping(address player => CreditBatch[] batches) private paidBatches;
    mapping(uint256 sessionId => BonusSession session) public bonusSessions;
    mapping(address player => uint256[] sessionIds) private playerBonusSessions;
    mapping(uint256 spinId => Spin spin) public spins;
    mapping(bytes32 requestHash => uint256 spinId) public requestToSpin;
    mapping(address player => uint256 spinId) public activeSpinOf;
    mapping(address player => uint256 spinId) public lastSpinOf;

    event BetLimitsChanged(
        uint256 previousMinimum,
        uint256 newMinimum,
        uint256 previousMaximum,
        uint256 newMaximum
    );
    event MathConfigProposed(uint32 indexed version, uint64 activatesAt, bytes32 configHash);
    event MathConfigActivated(uint32 indexed version, uint16 declaredRtpBps);
    event MathConfigCancelled(uint32 indexed version);
    event SpinsPurchased(
        address indexed player,
        uint256 indexed batchIndex,
        uint32 indexed mathVersion,
        uint256 wagerPerSpin,
        uint8 quantity,
        uint256 totalCost
    );
    event PaidSpinsRefunded(
        address indexed player,
        uint256 indexed batchIndex,
        uint8 quantity,
        uint256 amount
    );
    event SpinRequested(
        uint256 indexed spinId,
        bytes32 indexed requestHash,
        address indexed player,
        uint8 creditType,
        uint256 creditIndex,
        uint32 mathVersion,
        uint256 wager,
        uint256 maximumSessionPayout
    );
    event SpinSettled(
        uint256 indexed spinId,
        bytes32 indexed requestHash,
        address indexed player,
        uint8 creditType,
        uint256 sessionId,
        uint32 mathVersion,
        uint64 packedGrid,
        uint32 winningLinesMask,
        uint8 scatterCount,
        uint8 wildReel,
        uint8 freeSpinsAwarded,
        uint256 wager,
        uint256 payout,
        uint256 treasuryLoss
    );
    event BonusSessionCreated(
        uint256 indexed sessionId,
        address indexed player,
        uint256 indexed rootSpinId,
        uint32 mathVersion,
        uint256 wager,
        uint8 freeSpins,
        uint256 rootPayout,
        uint256 maximumSessionPayout
    );
    event BonusSessionCompleted(
        uint256 indexed sessionId,
        address indexed player,
        uint256 totalPayout,
        uint32 spinsPlayed,
        bool maximumWinReached
    );
    event BonusSessionForfeited(
        uint256 indexed sessionId,
        address indexed player,
        uint32 freeSpinsSurrendered
    );
    event StaleSpinRefunded(uint256 indexed spinId, address indexed player, uint8 creditType);
    event LateFulfillmentIgnored(bytes32 indexed requestHash, uint256 indexed spinId);

    error Unauthorized();
    error InvalidAddress();
    error InvalidAmount();
    error InvalidBetLimits();
    error InvalidQuantity();
    error InvalidBatch();
    error InvalidSession();
    error InvalidSpin();
    error InvalidMathConfiguration();
    error MathConfigurationNotReady();
    error PendingMathConfigurationExists();
    error ActiveSpinExists(uint256 spinId);
    error NoActiveCredit();
    error InsufficientBankroll(uint256 availableMaximumBet, uint256 requestedBet);
    error OnlyCoordinatorCanFulfill();
    error RequestNotStale();
    error UnsupportedToken();
    error MattLocked(uint256 protectedAmount);

    constructor(
        address mattToken,
        address rewardVaultAddress,
        address coordinatorAddress,
        address initialOwner,
        uint256[5] memory initialReels,
        uint32[30] memory initialLinePaysBps,
        uint32[3] memory initialScatterPaysBps,
        uint8[3] memory initialBonusAwards,
        uint16 initialDeclaredRtpBps
    ) Ownable(initialOwner) {
        if (
            mattToken == address(0) || rewardVaultAddress == address(0)
                || coordinatorAddress == address(0) || initialOwner == address(0)
        ) revert InvalidAddress();
        if (rewardVaultAddress.code.length == 0 || coordinatorAddress.code.length == 0) {
            revert InvalidAddress();
        }

        matt = IERC20(mattToken);
        rewardVault = IMattSlotsRewardVault(rewardVaultAddress);
        vrfCoordinator = IRoninVRFCoordinatorForMattSlots(coordinatorAddress);
        matt.forceApprove(rewardVaultAddress, type(uint256).max);

        _validateMathConfiguration(
            initialReels,
            initialLinePaysBps,
            initialScatterPaysBps,
            initialBonusAwards,
            initialDeclaredRtpBps
        );
        _storeMathConfiguration(
            1,
            initialReels,
            initialLinePaysBps,
            initialScatterPaysBps,
            initialBonusAwards,
            initialDeclaredRtpBps,
            uint64(block.timestamp)
        );
        _pause();
        emit MathConfigActivated(1, initialDeclaredRtpBps);
    }

    function buySpins(uint256 wagerPerSpin, uint8 quantity)
        external
        whenNotPaused
        nonReentrant
        returns (uint256 batchIndex)
    {
        if (
            wagerPerSpin < minBet || wagerPerSpin > maxBet
                || wagerPerSpin > type(uint96).max
        ) revert InvalidAmount();
        if (quantity < MIN_SPINS_PER_PURCHASE || quantity > MAX_SPINS_PER_PURCHASE) {
            revert InvalidQuantity();
        }
        uint256 playable = currentPlayableMaxBet();
        if (wagerPerSpin > playable) {
            revert InsufficientBankroll(playable, wagerPerSpin);
        }

        uint256 totalCost = wagerPerSpin * quantity;
        uint256 beforeBalance = matt.balanceOf(address(this));
        matt.safeTransferFrom(msg.sender, address(this), totalCost);
        if (matt.balanceOf(address(this)) - beforeBalance != totalCost) {
            revert InvalidAmount();
        }

        batchIndex = paidBatches[msg.sender].length;
        paidBatches[msg.sender].push(CreditBatch({
            wager: uint96(wagerPerSpin),
            remaining: quantity,
            purchased: quantity,
            mathVersion: activeMathVersion,
            purchasedAt: uint64(block.timestamp)
        }));
        totalCreditEscrow += totalCost;
        totalSpinsPurchased += quantity;

        emit SpinsPurchased(
            msg.sender,
            batchIndex,
            activeMathVersion,
            wagerPerSpin,
            quantity,
            totalCost
        );
    }

    /// @notice One click consumes exactly one prepaid credit and requests one fresh VRF seed.
    function playPaid(uint256 batchIndex)
        external
        payable
        whenNotPaused
        nonReentrant
        returns (uint256 spinId, bytes32 requestHash)
    {
        _requireNoActiveSpin(msg.sender);
        if (batchIndex >= paidBatches[msg.sender].length) revert InvalidBatch();
        CreditBatch storage batch = paidBatches[msg.sender][batchIndex];
        if (batch.remaining == 0) revert NoActiveCredit();

        uint256 playable = bankrollSupportedMaxBet();
        if (uint256(batch.wager) > playable) {
            revert InsufficientBankroll(playable, uint256(batch.wager));
        }

        batch.remaining -= 1;
        uint256 wager = uint256(batch.wager);
        totalCreditEscrow -= wager;
        totalPaidSpinsPlayed += 1;
        totalWagered += wager;

        spinId = _createSpin(
            msg.sender,
            wager,
            batch.mathVersion,
            uint32(batchIndex),
            CREDIT_PAID,
            0
        );
        uint256 maximumPayout = maxSessionPayout(wager);
        rewardVault.reservePaid(spinId, msg.sender, wager, maximumPayout);
        requestHash = _requestRandomness(spinId);

        emit SpinRequested(
            spinId,
            requestHash,
            msg.sender,
            CREDIT_PAID,
            batchIndex,
            batch.mathVersion,
            wager,
            maximumPayout
        );
    }

    function playBonus(uint256 sessionId)
        external
        payable
        whenNotPaused
        nonReentrant
        returns (uint256 spinId, bytes32 requestHash)
    {
        _requireNoActiveSpin(msg.sender);
        BonusSession storage session = bonusSessions[sessionId];
        if (
            session.player != msg.sender || session.completed || session.remaining == 0
        ) revert InvalidSession();

        session.remaining -= 1;
        session.totalPlayed += 1;
        totalBonusSpinsPlayed += 1;

        spinId = _createSpin(
            msg.sender,
            uint256(session.wager),
            session.mathVersion,
            0,
            CREDIT_BONUS,
            sessionId
        );
        requestHash = _requestRandomness(spinId);

        emit SpinRequested(
            spinId,
            requestHash,
            msg.sender,
            CREDIT_BONUS,
            sessionId,
            session.mathVersion,
            uint256(session.wager),
            maxSessionPayout(uint256(session.wager))
        );
    }

    function rawFulfillRandomSeed(bytes32 requestHash, uint256 randomSeed)
        external
        nonReentrant
    {
        if (msg.sender != address(vrfCoordinator)) revert OnlyCoordinatorCanFulfill();
        uint256 spinId = requestToSpin[requestHash];
        if (spinId == 0) revert InvalidSpin();
        Spin storage spin = spins[spinId];
        if (spin.status == SPIN_REFUNDED) {
            emit LateFulfillmentIgnored(requestHash, spinId);
            return;
        }
        if (spin.status != SPIN_PENDING) revert InvalidSpin();

        bool isBonus = spin.creditType == CREDIT_BONUS;
        (uint64 packedGrid, uint8 wildReel) = _generateGrid(
            randomSeed,
            requestHash,
            spinId,
            spin.mathVersion,
            isBonus
        );
        (
            uint256 multiplierBps,
            uint32 winningLinesMask,
            uint8 scatterCount,
            uint8 paidBonusAward
        ) = _evaluateGrid(spin.mathVersion, packedGrid);

        uint256 maximumPayout = maxSessionPayout(uint256(spin.wager));
        uint256 payout = Math.mulDiv(uint256(spin.wager), multiplierBps, BPS);
        uint8 freeSpinsAwarded;
        uint256 sessionId = spin.sessionId;
        bool sessionComplete;

        if (!isBonus) {
            if (payout > maximumPayout) payout = maximumPayout;
            if (paidBonusAward != 0 && payout < maximumPayout) {
                sessionId = nextSessionId++;
                freeSpinsAwarded = paidBonusAward > MAX_BONUS_SPINS
                    ? MAX_BONUS_SPINS
                    : paidBonusAward;
                bonusSessions[sessionId] = BonusSession({
                    player: spin.player,
                    wager: spin.wager,
                    remaining: freeSpinsAwarded,
                    totalAwarded: freeSpinsAwarded,
                    totalPlayed: 0,
                    mathVersion: spin.mathVersion,
                    rootSpinId: uint64(spinId),
                    totalPayout: payout,
                    completed: false
                });
                playerBonusSessions[spin.player].push(sessionId);
                emit BonusSessionCreated(
                    sessionId,
                    spin.player,
                    spinId,
                    spin.mathVersion,
                    uint256(spin.wager),
                    freeSpinsAwarded,
                    payout,
                    maximumPayout
                );
            }
        } else {
            BonusSession storage session = bonusSessions[sessionId];
            if (session.player != spin.player || session.completed) revert InvalidSession();
            uint256 remainingCap = maximumPayout - session.totalPayout;
            if (payout > remainingCap) payout = remainingCap;
            session.totalPayout += payout;

            if (
                scatterCount >= 3 && session.totalAwarded < MAX_BONUS_SPINS
                    && session.totalPayout < maximumPayout
            ) {
                uint8 retrigger = _retriggerAward(scatterCount);
                uint32 room = uint32(MAX_BONUS_SPINS) - session.totalAwarded;
                if (retrigger > room) retrigger = uint8(room);
                session.remaining += retrigger;
                session.totalAwarded += retrigger;
                freeSpinsAwarded = retrigger;
            }

            bool maximumReached = session.totalPayout >= maximumPayout;
            if (maximumReached) session.remaining = 0;
            sessionComplete = maximumReached || session.remaining == 0;
            if (sessionComplete) {
                session.completed = true;
                emit BonusSessionCompleted(
                    sessionId,
                    spin.player,
                    session.totalPayout,
                    session.totalPlayed,
                    maximumReached
                );
            }
        }

        uint256 treasuryLoss = !isBonus && uint256(spin.wager) > payout
            ? uint256(spin.wager) - payout
            : 0;

        spin.status = SPIN_SETTLED;
        spin.packedGrid = packedGrid;
        spin.winningLinesMask = winningLinesMask;
        spin.scatterCount = scatterCount;
        spin.wildReel = wildReel;
        spin.freeSpinsAwarded = freeSpinsAwarded;
        spin.sessionId = sessionId;
        spin.payout = payout;
        spin.treasuryLoss = treasuryLoss;
        activeSpinOf[spin.player] = 0;

        if (!isBonus) {
            rewardVault.settlePaid(spinId, payout, sessionId, sessionId != 0);
        } else {
            rewardVault.settleBonus(spinId, sessionId, payout, sessionComplete);
        }

        totalPaid += payout;
        totalTreasuryLoss += treasuryLoss;
        emit SpinSettled(
            spinId,
            requestHash,
            spin.player,
            spin.creditType,
            sessionId,
            spin.mathVersion,
            packedGrid,
            winningLinesMask,
            scatterCount,
            wildReel,
            freeSpinsAwarded,
            uint256(spin.wager),
            payout,
            treasuryLoss
        );
    }

    function refundStaleSpin(uint256 spinId) external nonReentrant {
        Spin storage spin = spins[spinId];
        if (spin.status != SPIN_PENDING) revert InvalidSpin();
        if (msg.sender != spin.player && msg.sender != owner()) revert Unauthorized();
        if (block.timestamp < uint256(spin.requestedAt) + STALE_REQUEST_DELAY) {
            revert RequestNotStale();
        }

        spin.status = SPIN_REFUNDED;
        if (activeSpinOf[spin.player] == spinId) activeSpinOf[spin.player] = 0;

        if (spin.creditType == CREDIT_PAID) {
            rewardVault.cancelPaid(spinId);
            CreditBatch storage batch = paidBatches[spin.player][spin.creditIndex];
            batch.remaining += 1;
            totalCreditEscrow += uint256(spin.wager);
            totalPaidSpinsPlayed -= 1;
            totalWagered -= uint256(spin.wager);
        } else if (spin.creditType == CREDIT_BONUS) {
            BonusSession storage session = bonusSessions[spin.sessionId];
            if (session.completed) revert InvalidSession();
            session.remaining += 1;
            session.totalPlayed -= 1;
            totalBonusSpinsPlayed -= 1;
        } else {
            revert InvalidSpin();
        }

        emit StaleSpinRefunded(spinId, spin.player, spin.creditType);
    }

    /// @notice Unused paid credits are redeemable for their original MATT value at any time.
    function refundPaidSpins(uint256 batchIndex, uint8 quantity) external nonReentrant {
        if (batchIndex >= paidBatches[msg.sender].length) revert InvalidBatch();
        CreditBatch storage batch = paidBatches[msg.sender][batchIndex];
        if (quantity == 0 || quantity > batch.remaining) revert InvalidQuantity();
        batch.remaining -= quantity;
        uint256 amount = uint256(batch.wager) * quantity;
        totalCreditEscrow -= amount;
        matt.safeTransfer(msg.sender, amount);
        emit PaidSpinsRefunded(msg.sender, batchIndex, quantity, amount);
    }

    function forfeitBonusSession(uint256 sessionId) external nonReentrant {
        BonusSession storage session = bonusSessions[sessionId];
        if (session.player != msg.sender || session.completed) revert InvalidSession();
        if (activeSpinOf[msg.sender] != 0) revert ActiveSpinExists(activeSpinOf[msg.sender]);
        uint32 surrendered = session.remaining;
        session.remaining = 0;
        session.completed = true;
        rewardVault.forfeitBonusSession(sessionId, msg.sender);
        emit BonusSessionForfeited(sessionId, msg.sender, surrendered);
        emit BonusSessionCompleted(
            sessionId,
            msg.sender,
            session.totalPayout,
            session.totalPlayed,
            false
        );
    }

    function setBetLimits(uint256 newMinimum, uint256 newMaximum) external onlyOwner {
        if (
            newMinimum == 0 || newMaximum < newMinimum
                || newMaximum > type(uint96).max
        ) revert InvalidBetLimits();
        uint256 previousMinimum = minBet;
        uint256 previousMaximum = maxBet;
        minBet = newMinimum;
        maxBet = newMaximum;
        emit BetLimitsChanged(
            previousMinimum,
            newMinimum,
            previousMaximum,
            newMaximum
        );
    }

    function proposeMathConfiguration(
        uint256[5] calldata reels,
        uint32[30] calldata linePaysBps,
        uint32[3] calldata scatterPaysBps,
        uint8[3] calldata bonusAwards,
        uint16 declaredRtpBps
    ) external onlyOwner whenPaused returns (uint32 version) {
        if (pendingMathVersion != 0) revert PendingMathConfigurationExists();
        _validateMathConfiguration(
            reels,
            linePaysBps,
            scatterPaysBps,
            bonusAwards,
            declaredRtpBps
        );
        version = ++latestMathVersion;
        uint64 activatesAt = uint64(block.timestamp + MATH_CONFIG_DELAY);
        _storeMathConfiguration(
            version,
            reels,
            linePaysBps,
            scatterPaysBps,
            bonusAwards,
            declaredRtpBps,
            activatesAt
        );
        pendingMathVersion = version;
        emit MathConfigProposed(
            version,
            activatesAt,
            keccak256(abi.encode(reels, linePaysBps, scatterPaysBps, bonusAwards, declaredRtpBps))
        );
    }

    function activateMathConfiguration(uint32 version) external onlyOwner whenPaused {
        if (version == 0 || version != pendingMathVersion) {
            revert InvalidMathConfiguration();
        }
        MathConfig storage config = mathConfigs[version];
        if (!config.exists || block.timestamp < config.activatesAt) {
            revert MathConfigurationNotReady();
        }
        activeMathVersion = version;
        pendingMathVersion = 0;
        emit MathConfigActivated(version, config.declaredRtpBps);
    }

    function cancelPendingMathConfiguration() external onlyOwner whenPaused {
        uint32 version = pendingMathVersion;
        if (version == 0) revert InvalidMathConfiguration();
        pendingMathVersion = 0;
        emit MathConfigCancelled(version);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        if (currentPlayableMaxBet() < minBet) {
            revert InsufficientBankroll(currentPlayableMaxBet(), minBet);
        }
        _unpause();
    }

    function quoteRandomFee() external view returns (uint256) {
        return vrfCoordinator.estimateRequestRandomFee(
            CALLBACK_GAS_LIMIT,
            fulfillmentGasPrice()
        );
    }

    function fulfillmentGasPrice() public view returns (uint256) {
        return 20 gwei + block.basefee * 2;
    }

    function maxSessionPayout(uint256 wager) public pure returns (uint256) {
        return Math.mulDiv(wager, MAX_MULTIPLIER_BPS, BPS);
    }

    function bankrollSupportedMaxBet() public view returns (uint256) {
        return Math.mulDiv(
            rewardVault.availableBankroll(),
            BPS,
            MAX_MULTIPLIER_BPS
        );
    }

    function currentPlayableMaxBet() public view returns (uint256) {
        uint256 bankrollSupported = bankrollSupportedMaxBet();
        return bankrollSupported < maxBet ? bankrollSupported : maxBet;
    }

    function paidBatchCount(address player) external view returns (uint256) {
        return paidBatches[player].length;
    }

    function paidBatchAt(address player, uint256 batchIndex)
        external
        view
        returns (CreditBatch memory)
    {
        if (batchIndex >= paidBatches[player].length) revert InvalidBatch();
        return paidBatches[player][batchIndex];
    }

    function playerBonusSessionCount(address player) external view returns (uint256) {
        return playerBonusSessions[player].length;
    }

    function playerBonusSessionIdAt(address player, uint256 index)
        external
        view
        returns (uint256)
    {
        if (index >= playerBonusSessions[player].length) revert InvalidSession();
        return playerBonusSessions[player][index];
    }

    function getSpinGrid(uint256 spinId) external view returns (uint8[15] memory grid) {
        Spin storage spin = spins[spinId];
        if (spin.status != SPIN_SETTLED) revert InvalidSpin();
        for (uint8 position = 0; position < 15; position++) {
            grid[position] = uint8((uint256(spin.packedGrid) >> (position * 4)) & 0x0f);
        }
    }

    function symbolAt(uint64 packedGrid, uint8 reel, uint8 row)
        public
        pure
        returns (uint8)
    {
        if (reel >= REELS || row >= ROWS) revert InvalidAmount();
        uint8 position = reel * ROWS + row;
        return uint8((uint256(packedGrid) >> (position * 4)) & 0x0f);
    }

    function getPayline(uint8 line) external pure returns (uint8[5] memory rows) {
        if (line >= PAYLINES) revert InvalidAmount();
        for (uint8 reel = 0; reel < REELS; reel++) {
            rows[reel] = _lineRow(line, reel);
        }
    }

    function getMathConfiguration(uint32 version)
        external
        view
        returns (
            uint256[5] memory reels,
            uint32[30] memory linePaysBps,
            uint32[3] memory scatterPaysBps,
            uint8[3] memory bonusAwards,
            uint16 declaredRtpBps,
            uint64 activatesAt,
            bool exists
        )
    {
        MathConfig storage config = mathConfigs[version];
        return (
            config.reels,
            config.linePaysBps,
            config.scatterPaysBps,
            config.bonusAwards,
            config.declaredRtpBps,
            config.activatesAt,
            config.exists
        );
    }

    function previewGrid(uint32 mathVersion, uint64 packedGrid)
        external
        view
        returns (
            uint256 multiplierBps,
            uint32 winningLinesMask,
            uint8 scatterCount,
            uint8 paidBonusAward
        )
    {
        return _evaluateGrid(mathVersion, packedGrid);
    }

    function recoverUnsupportedToken(address token, uint256 amount)
        external
        onlyOwner
        nonReentrant
    {
        if (token == address(matt)) revert UnsupportedToken();
        if (token == address(0) || amount == 0) revert InvalidAmount();
        IERC20(token).safeTransfer(owner(), amount);
    }

    function withdrawExcessMatt(uint256 amount) external onlyOwner whenPaused nonReentrant {
        uint256 balance = matt.balanceOf(address(this));
        uint256 excess = balance > totalCreditEscrow ? balance - totalCreditEscrow : 0;
        if (amount == 0 || amount > excess) revert MattLocked(totalCreditEscrow);
        matt.safeTransfer(owner(), amount);
    }

    function _createSpin(
        address player,
        uint256 wager,
        uint32 mathVersion,
        uint32 creditIndex,
        uint8 creditType,
        uint256 sessionId
    ) internal returns (uint256 spinId) {
        if (!mathConfigs[mathVersion].exists) revert InvalidMathConfiguration();
        spinId = nextSpinId++;
        uint256 previous = lastSpinOf[player];
        spins[spinId] = Spin({
            player: player,
            wager: uint96(wager),
            requestedAt: uint64(block.timestamp),
            previousPlayerSpinId: uint64(previous),
            mathVersion: mathVersion,
            creditIndex: creditIndex,
            creditType: creditType,
            status: SPIN_PENDING,
            wildReel: NO_WILD_REEL,
            scatterCount: 0,
            freeSpinsAwarded: 0,
            winningLinesMask: 0,
            packedGrid: 0,
            sessionId: sessionId,
            payout: 0,
            treasuryLoss: 0,
            requestHash: bytes32(0)
        });
        lastSpinOf[player] = spinId;
        activeSpinOf[player] = spinId;
    }

    function _requestRandomness(uint256 spinId) internal returns (bytes32 requestHash) {
        Spin storage spin = spins[spinId];
        requestHash = vrfCoordinator.requestRandomSeed{value: msg.value}(
            CALLBACK_GAS_LIMIT,
            fulfillmentGasPrice(),
            address(this),
            spin.player
        );
        if (requestHash == bytes32(0) || requestToSpin[requestHash] != 0) {
            revert InvalidSpin();
        }
        spin.requestHash = requestHash;
        requestToSpin[requestHash] = spinId;
    }

    function _generateGrid(
        uint256 randomSeed,
        bytes32 requestHash,
        uint256 spinId,
        uint32 mathVersion,
        bool bonus
    ) internal view returns (uint64 packedGrid, uint8 wildReel) {
        MathConfig storage config = mathConfigs[mathVersion];
        if (!config.exists) revert InvalidMathConfiguration();
        wildReel = bonus
            ? uint8(uint256(keccak256(abi.encode(randomSeed, requestHash, spinId, "WILD_REEL"))) % REELS)
            : NO_WILD_REEL;

        for (uint8 reel = 0; reel < REELS; reel++) {
            uint8 stop = uint8(
                uint256(keccak256(abi.encode(randomSeed, requestHash, spinId, reel))) & 63
            );
            for (uint8 row = 0; row < ROWS; row++) {
                uint8 symbol = reel == wildReel
                    ? WILD_SYMBOL
                    : _stripSymbol(config.reels[reel], uint8((stop + row) & 63));
                uint8 position = reel * ROWS + row;
                packedGrid |= uint64(symbol) << (position * 4);
            }
        }
    }

    function _evaluateGrid(uint32 mathVersion, uint64 packedGrid)
        internal
        view
        returns (
            uint256 multiplierBps,
            uint32 winningLinesMask,
            uint8 scatterCount,
            uint8 paidBonusAward
        )
    {
        MathConfig storage config = mathConfigs[mathVersion];
        if (!config.exists) revert InvalidMathConfiguration();

        for (uint8 line = 0; line < PAYLINES; line++) {
            uint256 lineWin = _lineWin(config, packedGrid, line);
            if (lineWin != 0) {
                multiplierBps += lineWin;
                winningLinesMask |= uint32(1) << line;
            }
        }

        for (uint8 reel = 0; reel < REELS; reel++) {
            for (uint8 row = 0; row < ROWS; row++) {
                if (symbolAt(packedGrid, reel, row) == SCATTER_SYMBOL) {
                    scatterCount += 1;
                }
            }
        }
        if (scatterCount >= 3) {
            uint8 index = scatterCount >= 5 ? 2 : scatterCount - 3;
            multiplierBps += config.scatterPaysBps[index];
            paidBonusAward = config.bonusAwards[index];
        }
        if (multiplierBps > MAX_MULTIPLIER_BPS) {
            multiplierBps = MAX_MULTIPLIER_BPS;
        }
    }

    function _lineWin(MathConfig storage config, uint64 packedGrid, uint8 line)
        internal
        view
        returns (uint256)
    {
        uint8 first = symbolAt(packedGrid, 0, _lineRow(line, 0));
        if (first == SCATTER_SYMBOL) return 0;

        uint8 target = WILD_SYMBOL;
        for (uint8 reel = 0; reel < REELS; reel++) {
            uint8 symbol = symbolAt(packedGrid, reel, _lineRow(line, reel));
            if (symbol == SCATTER_SYMBOL) break;
            if (symbol != WILD_SYMBOL) {
                target = symbol;
                break;
            }
        }

        uint8 count;
        for (uint8 reel = 0; reel < REELS; reel++) {
            uint8 symbol = symbolAt(packedGrid, reel, _lineRow(line, reel));
            if (symbol == SCATTER_SYMBOL) break;
            if (symbol == target || symbol == WILD_SYMBOL) count += 1;
            else break;
        }
        if (count < 3 || target >= SCATTER_SYMBOL) return 0;
        uint256 payIndex = uint256(target) * 3 + (count - 3);
        return config.linePaysBps[payIndex];
    }

    function _lineRow(uint8 line, uint8 reel) internal pure returns (uint8) {
        return uint8((PACKED_PAYLINES >> (uint256(line) * 10 + uint256(reel) * 2)) & 3);
    }

    function _stripSymbol(uint256 packedReel, uint8 index) internal pure returns (uint8) {
        return uint8((packedReel >> (uint256(index) * 4)) & 0x0f);
    }

    function _retriggerAward(uint8 scatterCount) internal pure returns (uint8) {
        if (scatterCount >= 5) return 12;
        if (scatterCount == 4) return 8;
        return 5;
    }

    function _requireNoActiveSpin(address player) internal view {
        uint256 active = activeSpinOf[player];
        if (active != 0) revert ActiveSpinExists(active);
    }

    function _validateMathConfiguration(
        uint256[5] memory reels,
        uint32[30] memory linePaysBps,
        uint32[3] memory scatterPaysBps,
        uint8[3] memory bonusAwards,
        uint16 declaredRtpBps
    ) internal pure {
        if (declaredRtpBps < 8_000 || declaredRtpBps > 10_000) {
            revert InvalidMathConfiguration();
        }
        for (uint8 reel = 0; reel < REELS; reel++) {
            uint8 scatterSymbols;
            uint8 wildSymbols;
            for (uint8 index = 0; index < 64; index++) {
                uint8 symbol = _stripSymbol(reels[reel], index);
                if (symbol >= SYMBOL_COUNT) revert InvalidMathConfiguration();
                if (symbol == SCATTER_SYMBOL) scatterSymbols += 1;
                if (symbol == WILD_SYMBOL) wildSymbols += 1;
            }
            if (
                scatterSymbols == 0 || scatterSymbols > 4
                    || wildSymbols == 0 || wildSymbols > 4
            ) revert InvalidMathConfiguration();
        }
        for (uint8 symbol = 0; symbol <= WILD_SYMBOL; symbol++) {
            uint256 offset = uint256(symbol) * 3;
            if (
                linePaysBps[offset] == 0
                    || linePaysBps[offset] > linePaysBps[offset + 1]
                    || linePaysBps[offset + 1] > linePaysBps[offset + 2]
            ) revert InvalidMathConfiguration();
        }
        if (
            scatterPaysBps[0] < BPS
                || scatterPaysBps[0] > scatterPaysBps[1]
                || scatterPaysBps[1] > scatterPaysBps[2]
                || bonusAwards[0] == 0
                || bonusAwards[0] > bonusAwards[1]
                || bonusAwards[1] > bonusAwards[2]
                || bonusAwards[2] > 25
        ) revert InvalidMathConfiguration();
    }

    function _storeMathConfiguration(
        uint32 version,
        uint256[5] memory reels,
        uint32[30] memory linePaysBps,
        uint32[3] memory scatterPaysBps,
        uint8[3] memory bonusAwards,
        uint16 declaredRtpBps,
        uint64 activatesAt
    ) internal {
        MathConfig storage config = mathConfigs[version];
        config.reels = reels;
        config.linePaysBps = linePaysBps;
        config.scatterPaysBps = scatterPaysBps;
        config.bonusAwards = bonusAwards;
        config.declaredRtpBps = declaredRtpBps;
        config.activatesAt = activatesAt;
        config.exists = true;
    }
}

